SELECT table_name, column_name, data_type FROM information_schema.columns
WHERE table_schema='warehouse' AND table_name IN ('shipping_notice_lines','stock_adjustments')
ORDER BY table_name, ordinal_position;

SELECT table_schema, table_name FROM information_schema.tables
WHERE table_schema NOT IN ('pg_catalog','information_schema')
ORDER BY table_schema, table_name;

SELECT kind, count(*) AS n, min(complaint_ts) AS first_ts, max(complaint_ts) AS last_ts
FROM payments.customer_complaints
GROUP BY kind ORDER BY n DESC;

SELECT count(*) rows, count(DISTINCT bill_id) bills, sum(amount_inr) FILTER (WHERE till_status='approved') approved_sum,
       count(*) FILTER (WHERE till_status='approved') approved_rows
FROM payments.pos_payments WHERE ts >= TIMESTAMP '2026-06-01' AND ts < TIMESTAMP '2026-07-01';

SELECT substring(bill_id from 10 for 2) AS till, count(DISTINCT bill_id) bills, count(*) rows, sum(amount_inr) FILTER (WHERE till_status='approved') amt
FROM payments.pos_payments WHERE ts >= TIMESTAMP '2026-06-01' AND ts < TIMESTAMP '2026-07-01'
GROUP BY 1 ORDER BY 1;

SELECT sku, gtin, name, pack, case_units, case_kg, flow, dc_slot, price_inr, cost_inr
FROM store.products
ORDER BY sku;

WITH june AS (
  SELECT * FROM payments.pos_payments
  WHERE ts >= DATE '2026-06-01' AND ts < DATE '2026-07-01'
),
bad AS (
  SELECT DISTINCT bill_id FROM june WHERE tender='UPI' AND till_status IN ('declined','failed','failed: no response')
),
paid AS (
  SELECT DISTINCT bill_id FROM june WHERE till_status='approved'
)
SELECT (SELECT count(*) FROM bad) AS bills_with_bad_upi,
       (SELECT count(*) FROM bad b WHERE b.bill_id NOT IN (SELECT bill_id FROM paid)) AS bills_never_paid,
       (SELECT count(*) FROM june WHERE tender='UPI' AND till_status IN ('declined','failed','failed: no response')) AS bad_attempts;

SELECT count(DISTINCT bill_id) AS bills_lines, count(*) AS lines,
       min(pos_ts)::text, max(pos_ts)::text
FROM store.pos_lines;

SELECT count(DISTINCT bill_id) AS june_bills_payments FROM payments.pos_payments WHERE ts >= '2026-06-01' AND ts < '2026-07-01';

SELECT count(DISTINCT l.bill_id) AS june_bills_with_lines
FROM store.pos_lines l WHERE l.pos_ts >= '2026-06-01' AND l.pos_ts < '2026-07-01';

SELECT count(DISTINCT bill_id) AS bills_lines, count(*) AS lines,
       min(pos_ts)::text AS mn, max(pos_ts)::text AS mx
FROM (SELECT bill_id, bill_ts AS pos_ts FROM store.pos_lines) x;

SELECT count(DISTINCT bill_id) AS june_bills_payments FROM payments.pos_payments WHERE ts >= '2026-06-01' AND ts < '2026-07-01';

SELECT count(DISTINCT l.bill_id) AS june_bills_with_lines
FROM store.pos_lines l WHERE l.bill_ts >= '2026-06-01' AND l.bill_ts < '2026-07-01';

SELECT count(*) AS lines_total, count(DISTINCT bill_id) AS bills_total,
       min(bill_ts)::text AS mn, max(bill_ts)::text AS mx
FROM store.pos_lines;

SELECT * FROM warehouse.pallets LIMIT 10;
SELECT * FROM warehouse.shipping_notice_lines LIMIT 10;
SELECT * FROM warehouse.stock_adjustments LIMIT 10;

SELECT status, count(*) FROM store.shelf_audits GROUP BY 1 ORDER BY 2 DESC;
SELECT reason, count(*), sum(units) FROM store.write_offs GROUP BY 1 ORDER BY 2 DESC;
SELECT trigger, count(*) FROM store.stock_counts GROUP BY 1 ORDER BY 2 DESC;

SELECT count(*) AS expired_writeoff_lines, sum(units) AS expired_units
FROM store.write_offs
WHERE reason = 'expired' AND date >= DATE '2026-06-01' AND date < DATE '2026-07-01';
